-- Private study notebook: one row per note, readable and writable only by its owner.
-- Ids are generated by the client so undo and the one-time import from browser storage
-- are idempotent upserts. Limits mirror noteSchema in src/shared/lib/validation.ts.

create table facodi.study_notes (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  learning_object_id uuid not null references facodi.learning_objects (id) on delete cascade,
  title text not null check (char_length(btrim(title)) between 1 and 160),
  body text not null default '' check (char_length(body) <= 8000),
  tags text[] not null default '{}'
    check (cardinality(tags) <= 12 and char_length(array_to_string(tags, ' ')) <= 400),
  timestamp_seconds integer check (timestamp_seconds between 0 and 999999),
  pinned boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table facodi.study_notes is
  'Private learner notes on a learning object, optionally anchored to a video time. Owner-only RLS.';

create index study_notes_owner_updated_idx on facodi.study_notes (owner_id, updated_at desc);
create index study_notes_learning_object_idx on facodi.study_notes (learning_object_id);

create trigger study_notes_set_updated_at
  before update on facodi.study_notes
  for each row execute function facodi.set_updated_at();

alter table facodi.study_notes enable row level security;

create policy "Owners read their study notes" on facodi.study_notes
  for select to authenticated
  using ((select auth.uid()) = owner_id);

create policy "Owners add their study notes" on facodi.study_notes
  for insert to authenticated
  with check ((select auth.uid()) = owner_id);

create policy "Owners edit their study notes" on facodi.study_notes
  for update to authenticated
  using ((select auth.uid()) = owner_id)
  with check ((select auth.uid()) = owner_id);

create policy "Owners delete their study notes" on facodi.study_notes
  for delete to authenticated
  using ((select auth.uid()) = owner_id);

revoke all on facodi.study_notes from public, anon, authenticated;
grant select, insert, update, delete on facodi.study_notes to authenticated;
